parameters.message:
A meeting-notes submission just arrived with NO notes in it, so nothing was extracted, saved or summarised — the AI step was skipped on purpose so it does not waste a call on an empty submission.

Title: {{ $json.title }}
Meeting date: {{ $json.meeting_date }}
Attendees: {{ $json.attendees }}
Received: {{ $json.received_at }}

Most likely cause: the form or shortcut sent an empty notes field. Re-send the meeting with the notes (or transcript) included.

A meeting was submitted but the AI extraction step failed, so no summary, tasks or log entry were created for it.

Meeting: {{ $('Normalise Meeting').first().json.title }}
Meeting date: {{ $('Normalise Meeting').first().json.meeting_date }}
Error: {{ $json.error.message }}

Common causes: an expired or out-of-credit OpenAI API key, or notes so long they exceeded the model context. Fix the cause and re-send the meeting notes to the webhook.

parameters.jsCode:
// Safe-parse the AI reply. If it is not valid JSON, fall back to an empty
// extraction with an honest summary line instead of failing the whole run —
// the meeting still gets logged and the owner still gets an email.
const raw = ($input.first().json.choices && $input.first().json.choices[0] && $input.first().json.choices[0].message && $input.first().json.choices[0].message.content) || '';
let parsed = null;
try { parsed = JSON.parse(raw); } catch (e) { parsed = null; }
const fallback = { summary: 'AI output could not be parsed — read the raw notes (saved in the Meeting Log).', decisions: [], tasks: [] };
const data = (parsed && typeof parsed === 'object') ? parsed : fallback;
const decisions = Array.isArray(data.decisions) ? data.decisions : [];
const tasks = Array.isArray(data.tasks) ? data.tasks : [];
const meeting = $('Normalise Meeting').first().json;
return [{ json: {
  meeting_title: meeting.title,
  meeting_date: meeting.meeting_date,
  attendees: meeting.attendees || '',
  config_owner_email: $('CONFIG — Edit Me').first().json.config_owner_email,
  summary: (typeof data.summary === 'string' && data.summary) ? data.summary : fallback.summary,
  decisions: decisions,
  tasks: tasks,
  task_count: tasks.length
} }];

// One item per extracted task, shaped for the Task List sheet.
// Zero tasks returns zero items: the Sheets branch simply ends, while the
// summary-email branch (which hangs off Parse Extraction in parallel)
// still fires — so a task-free meeting is still summarised and logged.
const data = $input.first().json;
const rows = [];
for (const t of (data.tasks || [])) {
  rows.push({ json: {
    meeting_title: data.meeting_title,
    meeting_date: data.meeting_date,
    task: t.task || '',
    owner: t.owner || 'Unassigned',
    due: t.due || 'Not specified',
    status: 'Open'
  } });
}
return rows;

// Build the owner's summary email as one plain-text block, and pass the
// log fields through in the same item so the Meeting Log node (connected
// in parallel with the email node) has everything it needs.
const d = $input.first().json;
const lines = [];
lines.push('Meeting: ' + d.meeting_title + ' (' + d.meeting_date + ')');
lines.push('Attendees: ' + (d.attendees || 'Not listed'));
lines.push('');
lines.push('SUMMARY');
lines.push(d.summary);
lines.push('');
lines.push('DECISIONS');
if (d.decisions && d.decisions.length) {
  d.decisions.forEach((x, i) => lines.push((i + 1) + '. ' + x));
} else {
  lines.push('No decisions captured.');
}
lines.push('');
lines.push('TASKS');
if (d.tasks && d.tasks.length) {
  d.tasks.forEach((t, i) => lines.push((i + 1) + '. ' + (t.task || '') + ' — Owner: ' + (t.owner || 'Unassigned') + ' — Due: ' + (t.due || 'Not specified')));
} else {
  lines.push('No tasks captured.');
}
return [{ json: {
  email_text: lines.join('\n'),
  meeting_title: d.meeting_title,
  meeting_date: d.meeting_date,
  attendees: d.attendees,
  summary: d.summary,
  task_count: d.task_count,
  config_owner_email: d.config_owner_email
} }];
